pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ACCURAL_DEPOSIT} from "../src/ACCURAL_DEPOSIT.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ACCURAL_DEPOSIT c;

    function setUp() public {
        c = new ACCURAL_DEPOSIT();
    }

    function _run(address newLog) internal {
        bool firstOk;
        try c.SetLogFile(newLog) {
            firstOk = true;
        } catch {
            firstOk = false;
        }
        try c.Initialized() {} catch { return; }
        bool secondOk;
        try c.SetLogFile(newLog) {
            secondOk = true;
        } catch {
            secondOk = false;
        }
        assertTrue(firstOk && !secondOk);
    }

    function testFuzz_run(address newLog) public {
        vm.assume(newLog.code.length == 0 && uint160(newLog) > 0xffff && newLog != address(this) && newLog != address(c) && newLog != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && newLog != 0x000000000000000000636F6e736F6c652e6c6f67 && newLog != 0x4e59b44847b379578588920cA78FbF26c0B4956C && newLog != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(newLog);
    }

    receive() external payable {}
}
